import type { AirLawQuestion } from "@/app/data/airlaw-questions";
import { NAV_BOOST_QUESTIONS } from "@/app/data/nav-questions-boost";
import { NAV_GAP_QUESTIONS } from "@/app/data/nav-questions-gap";
